#!/usr/bin/env python3
# usage: show.py FILE | show.py -s 'source'  -> runs original highlight and shows compact form
import sys, subprocess, re, html
ABBR = {'comment': 'C', 'string': 'S', 'number': 'N', 'const': 'K', 'keyword': 'W', 'type': 'T',
        'type-user': 'TU', 'prop': 'P', 'prop-user': 'PU', 'var': 'V', 'op': 'O', 'class': 'CL',
        'punct': 'U'}


def compact(out):
    def rep(m):
        k = m.group(1)
        t = html.unescape(m.group(2))
        return '[%s:%s]' % (ABBR.get(k, k), t)
    s = re.sub(r'<span class="lini-tok-([a-z-]+)">(.*?)</span>', rep, out, flags=re.S)
    return html.unescape(s)


def run(src=None, f=None, exe='/workspace/executable'):
    if src is not None:
        r = subprocess.run([exe, 'highlight', '-'], input=src.encode(), capture_output=True)
    else:
        r = subprocess.run([exe, 'highlight', f], capture_output=True)
    return r


if __name__ == '__main__':
    exe = '/workspace/executable'
    args = sys.argv[1:]
    if args and args[0] == '-m':
        exe = '/tmp/bin-hl/executable'
        args = args[1:]
    if args[0] == '-s':
        r = run(src=args[1], exe=exe)
    else:
        r = run(f=args[0], exe=exe)
    out = r.stdout.decode()
    print(compact(out), end='')
    if not out.endswith('\n'):
        print()
    if r.stderr:
        print('STDERR:', r.stderr.decode())
    if r.returncode:
        print('[exit %d]' % r.returncode)

