#!/usr/bin/env python3
# usage: tf.py [-m] FILE  -- each line of FILE is a snippet; escapes \n \t \r \\ are decoded.
# prints compact highlight of each snippet (original, or ours with -m; -d shows diffs orig vs ours)
import sys, subprocess
sys.path.insert(0, '/tmp/hl')
from show import compact
args = sys.argv[1:]
mode = 'orig'
if args and args[0] in ('-m', '-d'):
    mode = args[0]
    args = args[1:]


def dec(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s):
            n = s[i + 1]
            if n == 'n':
                out.append('\n'); i += 2; continue
            if n == 't':
                out.append('\t'); i += 2; continue
            if n == 'r':
                out.append('\r'); i += 2; continue
            if n == '\\':
                out.append('\\'); i += 2; continue
        out.append(c)
        i += 1
    return ''.join(out)


def run(exe, s):
    r = subprocess.run([exe, 'highlight', '-'], input=s.encode(), capture_output=True)
    return r


nd = 0
for line in open(args[0], encoding='utf-8').read().split('\n'):
    if line == '' or line.startswith('##'):
        continue
    s = dec(line)
    if mode == '-d':
        r1 = run('/workspace/executable', s)
        r2 = run('/tmp/bin-hl/executable', s)
        if r1.stdout != r2.stdout:
            nd += 1
            print('SNIP:', line)
            print('  O:', compact(r1.stdout.decode()).replace('\n', '⏎'))
            print('  M:', compact(r2.stdout.decode()).replace('\n', '⏎'))
        continue
    exe = '/tmp/bin-hl/executable' if mode == '-m' else '/workspace/executable'
    r = run(exe, s)
    out = compact(r.stdout.decode())
    print(out.replace('\n', '⏎'))
    if r.stderr or r.returncode:
        print('  STDERR:', r.stderr.decode(), 'exit', r.returncode)
if mode == '-d':
    print('DIFFS:', nd)

