#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Comment,
    Str,
    Number,
    Const,
    Keyword,
    Type,
    TypeUser,
    Prop,
    PropUser,
    Var,
    Op,
    Class,
    Punct,
}

impl Kind {
    fn class(self) -> &'static str {
        match self {
            Kind::Comment => "comment",
            Kind::Str => "string",
            Kind::Number => "number",
            Kind::Const => "const",
            Kind::Keyword => "keyword",
            Kind::Type => "type",
            Kind::TypeUser => "type-user",
            Kind::Prop => "prop",
            Kind::PropUser => "prop-user",
            Kind::Var => "var",
            Kind::Op => "op",
            Kind::Class => "class",
            Kind::Punct => "punct",
        }
    }
}

fn is_ident_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_'
}

fn is_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

struct Out {
    s: String,
}

impl Out {
    fn text(&mut self, t: &str) {
        for c in t.chars() {
            match c {
                '&' => self.s.push_str("&amp;"),
                '<' => self.s.push_str("&lt;"),
                '>' => self.s.push_str("&gt;"),
                '"' => self.s.push_str("&quot;"),
                _ => self.s.push(c),
            }
        }
    }
    fn span(&mut self, k: Kind, t: &str) {
        self.s.push_str("<span class=\"lini-tok-");
        self.s.push_str(k.class());
        self.s.push_str("\">");
        self.text(t);
        self.s.push_str("</span>");
    }
}

struct Scan<'a> {
    src: &'a str,
    b: &'a [u8],
}

impl<'a> Scan<'a> {
    fn at(&self, i: usize) -> u8 {
        if i < self.b.len() {
            self.b[i]
        } else {
            0
        }
    }
    fn ident_end(&self, mut i: usize) -> usize {
        while i < self.b.len() && is_ident_char(self.b[i]) {
            i += 1;
        }
        i
    }
    // length in bytes of the (possibly multi-byte) char at i
    fn char_len(&self, i: usize) -> usize {
        let c = self.b[i];
        if c < 0x80 {
            1
        } else if c >= 0xF0 {
            4
        } else if c >= 0xE0 {
            3
        } else if c >= 0xC0 {
            2
        } else {
            1
        }
    }
    // a number starting at i (optionally signed); returns end
    fn number_at(&self, i: usize, allow_minus: bool) -> Option<usize> {
        let mut j = i;
        let c = self.at(j);
        if c == b'+' || (allow_minus && c == b'-') {
            j += 1;
        }
        let d = self.at(j);
        if d.is_ascii_digit() {
            while self.at(j).is_ascii_digit() {
                j += 1;
            }
            if self.at(j) == b'.' && self.at(j + 1).is_ascii_digit() {
                j += 1;
                while self.at(j).is_ascii_digit() {
                    j += 1;
                }
            }
            Some(j)
        } else if d == b'.' && self.at(j + 1).is_ascii_digit() {
            j += 1;
            while self.at(j).is_ascii_digit() {
                j += 1;
            }
            Some(j)
        } else {
            None
        }
    }
    // `#` + 3/4/6/8 hex digits
    fn hex_at(&self, i: usize) -> Option<usize> {
        let mut j = i + 1;
        while self.at(j).is_ascii_hexdigit() {
            j += 1;
        }
        match j - i - 1 {
            3 | 4 | 6 | 8 => Some(j),
            _ => None,
        }
    }
    // `--` + ident
    fn var_at(&self, i: usize) -> Option<usize> {
        if self.at(i) == b'-' && self.at(i + 1) == b'-' && is_ident_start(self.at(i + 2)) {
            Some(self.ident_end(i + 2))
        } else {
            None
        }
    }
    // link operator: head? body tail?
    fn op_at(&self, i: usize) -> Option<usize> {
        if self.at(i) == b'&' {
            return Some(i + 1);
        }
        let mut j = i;
        // head
        if self.at(j) == b'<' && self.at(j + 1) == b'>' {
            j += 2;
        } else if matches!(self.at(j), b'<' | b'>' | b'*') {
            j += 1;
        }
        // body
        if self.at(j) == b'-' {
            let mut k = 0;
            while self.at(j) == b'-' && k < 3 {
                j += 1;
                k += 1;
            }
        } else if self.at(j) == b'~' {
            j += 1;
        } else {
            return None;
        }
        // tail
        if self.at(j) == b'<' && self.at(j + 1) == b'>' {
            j += 2;
        } else if matches!(self.at(j), b'<' | b'>' | b'*') {
            j += 1;
        }
        Some(j)
    }
    // class: `.` ident (`.` ident)*
    fn class_at(&self, i: usize) -> Option<usize> {
        if self.at(i) != b'.' || !is_ident_start(self.at(i + 1)) {
            return None;
        }
        let mut j = self.ident_end(i + 1);
        while self.at(j) == b'.' && is_ident_start(self.at(j + 1)) {
            j = self.ident_end(j + 1);
        }
        Some(j)
    }
    fn prev_is_ident(&self, i: usize) -> bool {
        i > 0 && is_ident_char(self.b[i - 1])
    }
    // string from i (at '"'): to the closing quote, or to end of line
    fn string_end(&self, i: usize) -> usize {
        let mut j = i + 1;
        while j < self.b.len() {
            match self.b[j] {
                b'"' => return j + 1,
                b'\n' => return j,
                b'\\' => {
                    if j + 1 < self.b.len() && self.b[j + 1] != b'\n' {
                        j += 2;
                    } else {
                        j += 1;
                    }
                }
                _ => j += 1,
            }
        }
        j
    }
    fn line_end(&self, i: usize) -> usize {
        let mut j = i;
        while j < self.b.len() && self.b[j] != b'\n' {
            j += 1;
        }
        j
    }
    fn skip_blank(&self, mut i: usize) -> usize {
        while matches!(self.at(i), b' ' | b'\t') {
            i += 1;
        }
        i
    }
    fn s(&self, a: usize, b: usize) -> &'a str {
        &self.src[a..b]
    }
}

pub fn highlight(src: &str) -> String {
    let sc = Scan { src, b: src.as_bytes() };
    let b = sc.b;
    let n = b.len();
    let mut o = Out { s: String::with_capacity(src.len() * 3) };
    let mut i = 0;
    let mut value = false;
    let mut bars = false;
    let mut after_hash = false;
    while i < n {
        let c = b[i];
        if c == b'\n' {
            o.s.push('\n');
            value = false;
            bars = false;
            after_hash = false;
            i += 1;
            continue;
        }
        if bars {
            let was_hash = after_hash;
            after_hash = false;
            if c == b'|' {
                o.span(Kind::Punct, "|");
                bars = false;
                i += 1;
            } else if c == b'#' {
                o.span(Kind::Punct, "#");
                after_hash = true;
                i += 1;
            } else if c == b':' && sc.at(i + 1) == b':' {
                o.span(Kind::Op, "::");
                i += 2;
            } else if let Some(e) = sc.class_at(i) {
                o.span(Kind::Class, sc.s(i, e));
                i = e;
            } else if is_ident_start(c) {
                let e = sc.ident_end(i);
                let w = sc.s(i, e);
                let k = if was_hash || TYPES.contains(&w) { Kind::Type } else { Kind::TypeUser };
                o.span(k, w);
                i = e;
            } else {
                let l = sc.char_len(i);
                o.text(sc.s(i, i + l));
                i += l;
            }
            continue;
        }
        // comments and strings: both modes
        if c == b'/' && sc.at(i + 1) == b'/' {
            let e = sc.line_end(i);
            o.span(Kind::Comment, sc.s(i, e));
            i = e;
            continue;
        }
        if c == b'"' {
            let e = sc.string_end(i);
            o.span(Kind::Str, sc.s(i, e));
            i = e;
            continue;
        }
        if value {
            match c {
                b';' | b'}' | b']' => {
                    o.span(Kind::Punct, sc.s(i, i + 1));
                    value = false;
                    i += 1;
                    continue;
                }
                b'(' | b')' | b',' => {
                    o.span(Kind::Punct, sc.s(i, i + 1));
                    i += 1;
                    continue;
                }
                _ => {}
            }
            if let Some(e) = sc.var_at(i) {
                o.span(Kind::Var, sc.s(i, e));
                i = e;
                continue;
            }
            if let Some(e) = sc.number_at(i, true) {
                o.span(Kind::Number, sc.s(i, e));
                i = e;
                continue;
            }
            if c == b'#' {
                if let Some(e) = sc.hex_at(i) {
                    o.span(Kind::Const, sc.s(i, e));
                    i = e;
                    continue;
                }
            }
            if is_ident_start(c) {
                let e = sc.ident_end(i);
                let w = sc.s(i, e);
                let k = if FUNCS.contains(&w) && sc.at(sc.skip_blank(e)) == b'(' {
                    Some(Kind::Type)
                } else if COLORS.contains(&w) {
                    Some(Kind::Const)
                } else if KEYWORDS.contains(&w) {
                    Some(Kind::Keyword)
                } else {
                    None
                };
                match k {
                    Some(k) => o.span(k, w),
                    None => o.text(w),
                }
                i = e;
                continue;
            }
            let l = sc.char_len(i);
            o.text(sc.s(i, i + l));
            i += l;
            continue;
        }
        // normal mode
        match c {
            b'|' => {
                o.span(Kind::Punct, "|");
                bars = true;
                i += 1;
                continue;
            }
            b'{' | b'}' | b'[' | b']' | b'(' | b')' | b';' | b',' => {
                o.span(Kind::Punct, sc.s(i, i + 1));
                i += 1;
                continue;
            }
            b':' => {
                o.span(Kind::Punct, ":");
                value = true;
                i += 1;
                continue;
            }
            _ => {}
        }
        if let Some(e) = sc.var_at(i) {
            o.span(Kind::Var, sc.s(i, e));
            i = e;
            continue;
        }
        if let Some(e) = sc.op_at(i) {
            o.span(Kind::Op, sc.s(i, e));
            i = e;
            continue;
        }
        if let Some(e) = sc.number_at(i, false) {
            o.span(Kind::Number, sc.s(i, e));
            i = e;
            continue;
        }
        if c == b'#' {
            if let Some(e) = sc.hex_at(i) {
                o.span(Kind::Const, sc.s(i, e));
                i = e;
                continue;
            }
        }
        if c == b'.' && !sc.prev_is_ident(i) {
            if let Some(e) = sc.class_at(i) {
                o.span(Kind::Class, sc.s(i, e));
                i = e;
                continue;
            }
        }
        if is_ident_start(c) {
            let e = sc.ident_end(i);
            let w = sc.s(i, e);
            // `name:` (not `::`, not `name:side`) is a declaration
            let k = sc.skip_blank(e);
            let is_prop = sc.at(k) == b':' && sc.at(k + 1) != b':' && {
                let ve = sc.ident_end(k + 1);
                !(is_ident_start(sc.at(k + 1)) && SIDES.contains(&sc.s(k + 1, ve)))
            };
            if is_prop {
                o.span(if PROPS.contains(&w) { Kind::Prop } else { Kind::PropUser }, w);
            } else if SIDES.contains(&w) {
                o.span(Kind::Const, w);
            } else {
                o.text(w);
            }
            i = e;
            continue;
        }
        let l = sc.char_len(i);
        o.text(sc.s(i, i + l));
        i += l;
    }
    o.s
}

#!/usr/bin/env python3
# random differential fuzzing of `highlight` (original vs ours)
import sys, random, subprocess, json
sys.path.insert(0, '/tmp/hl')
from show import compact
ORIG = '/workspace/executable'
MINE = '/tmp/bin-hl/executable'
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
lines_per = int(sys.argv[3]) if len(sys.argv) > 3 else 400
rng = random.Random(seed)
cls = json.load(open('/tmp/hl/all_cls.json'))
interesting = [w for w in cls if any(v not in ('-', 'TU', 'PU', 'N') for v in cls[w].values())]
plainwords = ['a', 'b', 'x', 'foo', 'n1', 'A', '_x', 'a-b', 'x_1', 'é', 'π', 'a1']
puncts = list('{}[]();,:|#.') + ['::', '//', '"', '\\', '\\"']
opch = list('-<>*~&+o=') + ['->', '-->', '<->', '~>', '-o<', '(-)', '(o)', '||', '<>', '--']
misc = list('@$%!?`\'^/=+') + ['\t', '\r', '\u00a0', '→', '⌀', 'é']
nums = ['0', '5', '12', '1.5', '.5', '-5', '+5', '-.5', '5.', '1e3', '50%', '5px', '007', '1.2.3']


def tok():
    r = rng.random()
    if r < 0.25:
        return rng.choice(interesting)
    if r < 0.33:
        return rng.choice(plainwords)
    if r < 0.50:
        return rng.choice(puncts)
    if r < 0.62:
        return rng.choice(opch)
    if r < 0.70:
        return rng.choice(misc)
    if r < 0.80:
        return rng.choice(nums)
    if r < 0.85:
        return '#' + ''.join(rng.choice('0123456789abcdefABCDEFxg') for _ in range(rng.randint(0, 9)))
    if r < 0.89:
        return '--' + rng.choice(interesting + plainwords)
    if r < 0.93:
        return '.' + rng.choice(interesting + plainwords)
    if r < 0.96:
        return '"' + ''.join(rng.choice('ab \\"/') for _ in range(rng.randint(0, 5))) + rng.choice(['"', ''])
    return '// ' + rng.choice(interesting)


def line():
    n = rng.randint(1, 10)
    parts = []
    for _ in range(n):
        parts.append(tok())
        parts.append(rng.choice(['', '', ' ', ' ', '  ', '\t']))
    return ''.join(parts).replace('\n', ' ')


def run(exe, s):
    return subprocess.run([exe, 'highlight', '-'], input=s.encode(), capture_output=True).stdout


def same(s):
    return run(ORIG, s) == run(MINE, s)


def minimize(s):
    # delta-debug by removing chars
    changed = True
    while changed:
        changed = False
        for size in (8, 4, 2, 1):
            i = 0
            while i < len(s):
                t = s[:i] + s[i + size:]
                if t and not same(t):
                    s = t
                    changed = True
                else:
                    i += size
    return s


bad = []
for r in range(rounds):
    ls = [line() for _ in range(lines_per)]
    src = '\n'.join(ls) + '\n'
    o1 = run(ORIG, src)
    o2 = run(MINE, src)
    if o1 == o2:
        continue
    a = o1.decode().split('\n')
    b = o2.decode().split('\n')
    for k, l in enumerate(ls):
        if k < len(a) and k < len(b) and a[k] == b[k]:
