#!/usr/bin/env python3
# verify every word of the JS lists against the original binary, and compare with ours
import sys, re
sys.path.insert(0, '/tmp/hl')
from batch import batch
js = open('/tmp/hl/tok.js').read()


def lst(name):
    m = re.search(name + r' =\s*/\(\?:([^)]*)\)', js)
    return m.group(1).split('|')


lists = {
    'TYPE_BUILTIN': (lst('TYPE_BUILTIN'), '|%s|', 'T'),
    'PROP_KNOWN': (lst('PROP_KNOWN'), '%s: 1', 'P'),
    'BUILDER': (lst('BUILDER'), 'x: %s(1)', 'T'),
    'KEYWORD': (lst('KEYWORD'), 'x: %s', 'W'),
    'COLOR': (lst('COLOR'), 'x: %s', 'K'),
    'SIDE': (lst('SIDE'), '%s', 'K'),
}
for exe in ['/workspace/executable', '/tmp/bin-hl/executable']:
    for name, (words, fmt, kind) in lists.items():
        out = batch([fmt % w for w in words], exe=exe)
        bad = [w for w, o in zip(words, out) if '[%s:%s]' % (kind, w) not in o]
        print(exe, name, len(words), 'bad:', bad)

