#!/usr/bin/env python3
# 3-way differential fuzz: original vs ours vs playground JS; token-level generator
import sys, random, subprocess, json, tempfile, os
sys.path.insert(0, '/tmp/hl')
ORIG = '/workspace/executable'
MINE = '/tmp/bin-hl/executable'
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 20
per = int(sys.argv[3]) if len(sys.argv) > 3 else 500
rng = random.Random(seed)
cls = json.load(open('/tmp/hl/all_cls.json'))
interesting = [w for w in cls if any(v not in ('-', 'TU', 'PU', 'N') for v in cls[w].values())]
interesting += ['breakline', 'door-leaf', 'window-sill', 'rgb', 'hsla', 'currentColor']
plainwords = ['a', 'b', 'x', 'foo', 'n1', 'A', '_x', 'a-b', 'x_1', 'é', 'π', 'a1', 'left5', 'leftx', 'top-left']
puncts = list('{}[]();,:|#.') + ['::', '//', '"', '\\', '\\"', ':left', ':top', ': ', '\\\r', '\\\n']
opch = list('-<>*~&+o=') + ['->', '-->', '<->', '~>', '-o<', '(-)', '(o)', '||', '<>', '--', '---', '<>-', '-<>']
misc = list('@$%!?`\'^/=+') + ['\t', '\r', '\n', '\x0c', '\x0b', ' ', ' ', '→', '⌀', 'é', '𝒳', '٣', 'ａ', '\x00']
nums = ['0', '5', '12', '1.5', '.5', '-5', '+5', '-.5', '5.', '1e3', '50%', '5px', '007', '1.2.3', '+.5', '-0.5']


def tok():
    r = rng.random()
    if r < 0.25:
        return rng.choice(interesting)
    if r < 0.33:
        return rng.choice(plainwords)
    if r < 0.50:
        return rng.choice(puncts)
    if r < 0.62:
        return rng.choice(opch)
    if r < 0.70:
        return rng.choice(misc)
    if r < 0.80:
        return rng.choice(nums)
    if r < 0.85:
        return '#' + ''.join(rng.choice('0123456789abcdefABCDEFxg') for _ in range(rng.randint(0, 9)))
    if r < 0.89:
        return '--' + rng.choice(interesting + plainwords)
    if r < 0.93:
        return '.' + rng.choice(interesting + plainwords)
    if r < 0.96:
        return '"' + ''.join(rng.choice('ab \\"/\r') for _ in range(rng.randint(0, 5))) + rng.choice(['"', ''])
    return '// ' + rng.choice(interesting)


def line():
    n = rng.randint(1, 12)
    parts = []
    for _ in range(n):
        parts.append(tok())
        parts.append(rng.choice(['', '', ' ', ' ', '  ', '\t']))
    return ''.join(parts)


def run_bin(exe, s):
    return subprocess.run([exe, 'highlight', '-'], input=s.encode(), capture_output=True).stdout


def run_js(s):
    fd, path = tempfile.mkstemp(dir='/tmp/hl', suffix='.lini')
    os.write(fd, s.encode())
    os.close(fd)
    try:
        r = subprocess.run(['node', '/tmp/hl/tok.js', path], capture_output=True)
        return r.stdout
    finally:
        os.unlink(path)


def minimize(s, pred):
    changed = True
    while changed:
        changed = False
        for size in (16, 8, 4, 2, 1):
            i = 0
            while i < len(s):
                t = s[:i] + s[i + size:]
                if t and pred(t):
                    s = t
                    changed = True
                else:
                    i += size
    return s


seen_m = set()
seen_j = set()
for r in range(rounds):
    src = '\n'.join(line() for _ in range(per)) + '\n'
    ls = src.split('\n')[:-1]
    o = run_bin(ORIG, src).decode().split('\n')
    m = run_bin(MINE, src).decode().split('\n')
    j = run_js(src).decode().split('\n')
    for k, l in enumerate(ls):
        if o[k] != m[k]:
            mm = minimize(l, lambda t: run_bin(ORIG, t) != run_bin(MINE, t))
            if mm not in seen_m:
                seen_m.add(mm)
                print('MINE-DIFF', repr(mm))
                print('    O', repr(run_bin(ORIG, mm).decode()))
                print('    M', repr(run_bin(MINE, mm).decode()))
        if o[k] != j[k] and len(seen_j) < 30:
            mj = minimize(l, lambda t: run_bin(ORIG, t) != run_js(t))
            if mj not in seen_j:
                seen_j.add(mj)
                print('JS-DIFF', repr(mj))
                print('    O', repr(run_bin(ORIG, mj).decode()))
                print('    J', repr(run_js(mj).decode()))
print('mine diffs', len(seen_m), 'js diffs', len(seen_j))

