#!/usr/bin/env python3
# materialise the snippet files (s*.txt, one snippet per line, escapes decoded) as .lini files
import glob, os, random, sys
sys.path.insert(0, '/tmp/hl')
os.makedirs('/tmp/hl/corpus', exist_ok=True)
for f in glob.glob('/tmp/hl/corpus/*.lini'):
    os.unlink(f)


def dec(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s) and s[i + 1] in 'ntr\\':
            out.append({'n': '\n', 't': '\t', 'r': '\r', '\\': '\\'}[s[i + 1]])
            i += 2
            continue
        out.append(c)
        i += 1
    return ''.join(out)


n = 0
for f in sorted(glob.glob('/tmp/hl/s[0-9]*.txt')):
    base = os.path.basename(f)[:-4]
    for k, line in enumerate(open(f, encoding='utf-8').read().split('\n')):
        if not line or line.startswith('##'):
            continue
        open('/tmp/hl/corpus/%s_%03d.lini' % (base, k), 'w', encoding='utf-8', newline='').write(dec(line))
        n += 1
# a few multi-line random documents built from asset lines + mutations
rng = random.Random(5)
lines = []
for f in glob.glob('/workspace/assets/**/*.lini', recursive=True):
    lines += open(f, encoding='utf-8').read().split('\n')
for k in range(100):
    doc = []
    for _ in range(rng.randint(3, 30)):
        l = list(rng.choice(lines))
        for _ in range(rng.randint(0, 3)):
            p = rng.randrange(len(l) + 1)
            l[p:p] = list(rng.choice(['|', '#', ':', '"', '\\', '-', '>', '.', '\r', '\t', '{', '}', ';', '//', 'left', 'rgb(', 'é']))
        doc.append(''.join(l))
    open('/tmp/hl/corpus/doc_%03d.lini' % k, 'w', encoding='utf-8', newline='').write('\n'.join(doc) + rng.choice(['', '\n', '\r\n']))
    n += 1
print(n)

